package com.hpe.morpheus.harvester.plugin.apihelper

import com.hpe.morpheus.harvester.plugin.utils.HarvesterConstants
import com.morpheusdata.model.ComputeServerGroup
import com.morpheusdata.response.ServiceResponse
import groovy.util.logging.Slf4j

/**
 * Helper class for Harvester Project API operations
 * Purpose: Provides high-level API methods for Harvester project operations
 * Author: Generated by GitHub Copilot
 * Date: August 19, 2025
 */
@Slf4j
class ProjectApiHelper {

    // Instance fields for configuration
    private ComputeServerGroup serverGroup
    private HarvesterApiClient apiClient

    /**
     * Create instance with ComputeServerGroup credentials
     * @param serverGroup ComputeServerGroup containing credentials
     */
    ProjectApiHelper(ComputeServerGroup serverGroup = null) {
        this.serverGroup = serverGroup
        this.apiClient = new HarvesterApiClient(serverGroup)
        log.debug "Initialized ProjectApiHelper with authentication"
    }

    def getProjects() {
        def ret = [success: true, projects: []]
        // Harvester projects are Kubernetes namespaces
        ServiceResponse response = apiClient.get(HarvesterConstants.HARVESTER_API_V1_NAMESPACES)
        if (response.success == true) {
            def projects = response.data?.items ?: []
            projects.each { project ->
                String projectName = project.metadata.name
                // Filter out system namespaces
                if (!CommonApiHelper.isSystemNamespace(projectName)) {
                    def projectData = [
                        uid: project.metadata.uid,
                        name: project.metadata.name,
                        description: project.metadata.annotations?.description ?: project.metadata.annotations?.'field.cattle.io/description' ?: '',
                        status: project.status.phase ?: 'Unknown',
                    ]
                    ret.projects << projectData
                }
            }
            ret.success = true
            log.debug("Fetched ${ret.projects.size()} projects from Harvester")
        } else{
            log.error("Failed to fetch projects from Harvester: ${response.msg}," +
                    " errorCode:${response.errorCode}, statusCode:${response.statusCode}")
            ret.success = false
            ret.message = response.msg ?: 'Failed to fetch projects from Harvester'
        }
        return ret
    }
}
